    "冷凝法": (0, 0, 65, 0, 0, 0, 0),
    "吸附/催化燃烧法": (0, 0, 85, 0, 0, 0, 0),
    "催化燃烧法": (0, 0, 85, 0, 0, 0, 0),
    "低温等离子体": (0, 0, 39, 0, 0, 0, 0),
    "生物过滤法": (0, 0, 53, 0, 0, 0, 0),
    "溶剂法": (0, 0, 12, 0, 0, 0, 0),
    "热力燃烧": (0, 0, 90, 0, 0, 0, 0),
    "无控制技术": (0, 0, 0, 0, 0, 0, 0),
}
A1_COLS = {"SO2": 0, "NOx": 1, "VOC": 2, "PM2.5": 3, "PM10": 4, "BC": 5, "OC": 6}
PM_COARSE_COL = 4  # PM2.5-10 列

# 治理工艺 -> A1 措施名 (关键词匹配, 返回匹配到的措施列表)
def match_a1_so2(proc):
    m = []
    if not isinstance(proc, str) or not proc.strip():
        return m
    p = proc
    if "炉内脱硫" in p or "炉内喷钙" in p:
        m.append("炉内喷钙法")
    if "双碱法" in p:
        m.append("双碱法")
    if "石灰石/石膏法" in p or "石灰/石膏法" in p:
        m.append("石灰石/石膏法")
    if "烟气循环流化床" in p:
        m.append("烟气循环流化床法")
    if "旋转喷雾" in p:
        m.append("旋转喷雾干燥法")
    if "氨法" in p:
        m.append("氨法")
    if "钠碱法" in p or "湿法脱硫除尘一体化" in p:
        m.append("其他脱硫技术")
    if "湿法除尘" in p or "文丘里" in p or "喷淋" in p or "水浴" in p or "湿式喷雾" in p or "水膜" in p:
        m.append("湿式除尘法")
    return m

def match_a1_nox(proc):
    if not isinstance(proc, str) or not proc.strip():
        return []
    p = proc
    has_lnb = "低氮燃烧" in p
    has_scr = ("SCR" in p) or ("催化还原" in p and "非" not in p.split("催化还原")[0][-2:] and "非催化" not in p)
    has_sncr = ("SNCR" in p) or ("非催化还原" in p)
    if has_lnb and has_scr:
        return ["低氮燃烧技术+选择性催化还原法"]
    if has_lnb and has_sncr:
        return ["低氮燃烧技术+选择性非催化还原法"]
    if has_scr or ("SNCR+SCR" in p) or ("SCR" in p and "SNCR" in p):
        return ["选择性催化还原法"]
    if has_sncr:
        return ["选择性非催化还原法"]
    if has_lnb or "烟气循环燃烧" in p:
        return ["低氮燃烧技术"]
    return []

def match_a1_pm(proc):
    if not isinstance(proc, str) or not proc.strip():
        return []
    p = proc
    m = []
    if "袋式" in p:
        m.append("袋式除尘法")
    if "电袋" in p:
        m.append("电袋复合除尘法")
    if "湿式电除尘" in p:
        m.append("高效静电除尘法")
    elif "静电" in p:
        m.append("高效静电除尘法" if "高效" in p else "普通静电除尘法")
    if "多管旋风" in p or "单筒" in p or ("旋风" in p and "袋式" not in p):
        m.append("多管旋风除尘法")
    if "喷淋" in p or "冲击水浴" in p or "湿式喷雾" in p or "文丘里" in p or "水膜" in p or "湿法除尘" in p:
        m.append("湿式除尘法")
    if "重力沉降" in p:
        m.append("重力沉降法")
    if "惯性" in p:
        m.append("惯性除尘法")
    if "无组织" in p:
        m.append("无组织尘高效控制技术" if "高效" in p else "无组织尘一般控制技术")
    return m

def match_a1_voc(proc):
    if not isinstance(proc, str) or not proc.strip():
        return []
    p = proc
    for key in ["吸附/催化燃烧法", "蓄热式热力燃烧法", "催化燃烧法", "沸石转轮吸附法",
                "低温等离子体", "生物过滤法", "冷凝法", "光催化", "光解", "活性炭法",
                "热力燃烧", "溶剂法"]:
        if key in p:
            return [key]
    if "活性炭" in p:
        return ["活性炭法"]
    return []

