def load_inputs():
    b102 = pd.read_excel(os.path.join(INPUTS, "基102-2002_原始结构脱敏输入.xlsx"), sheet_name="Sheet1")
    b10102 = pd.read_excel(os.path.join(INPUTS, "基101-2002_原始结构脱敏输入.xlsx"), sheet_name="Sheet1")
    with open(os.path.join(INPUTS, "source_identity_index.json"), encoding="utf-8") as f:
        idx = json.load(f)
    return b102, b10102, idx

def attach_source_ids(b102, idx):
    recs = idx["records"]
    assert len(recs) == len(b102), f"records {len(recs)} != b102 rows {len(b102)}"
    rows = {}
    for r in recs:
        rows[r["source_row"]] = r["source_id"]
    # 校验连续覆盖
    assert set(rows.keys()) == set(range(2, 2 + len(b102))), "source_row coverage broken"
    b102 = b102.copy()
    b102["source_id"] = [rows[i] for i in range(2, 2 + len(b102))]
    assert b102["source_id"].nunique() == len(b102), "source_id not unique"
    return b102

def classify_industry(ind):
    if ind is None or (isinstance(ind, float) and math.isnan(ind)):
        return "OUT_OF_SCOPE", "ind_missing"
    ind = int(ind)
    if ind in (4411, 4412, 4417, 4430):
        return "POWER_HEAT", "power_heat_enterprise_4411_4412_4417_4430"
    s = str(ind)
    pre2 = s[:2]
    mining = {"06", "07", "08", "09", "10", "11", "12"}
    manuf = {str(x) for x in range(13, 44)}
    if pre2 in mining or pre2 in manuf or pre2 == "45":
        return "INDUSTRIAL", "industrial_enterprise_B_C_D45"
    if pre2 == "44":
        return "OUT_OF_SCOPE", "out_of_scope_4419_other_power"
    if pre2 == "46":
        return "OUT_OF_SCOPE", "out_of_scope_46_water_supply"
    if pre2 == "05":
        return "OUT_OF_SCOPE", "out_of_scope_05_agriculture_service"
    return "OUT_OF_SCOPE", "out_of_scope_other"

