def facility_service(name):
    n = str(name)
    if "除尘" in n:
        return "PM"
    if "脱硫" in n:
        return "SO2"
    if "脱硝" in n:
        return "NOx"
    if "挥发性有机物" in n:
        return "VOC"
    return "OTHER"

def facility_eff(fac, service, low_nox):
    """返回该设施对各污染物的去除效率 dict; 无有效信息 -> None"""
    eff = fac.get("治理效率（%）")
    reported = None
    if eff is not None and not (isinstance(eff, float) and math.isnan(eff)):
        if 0.0 <= float(eff) <= 100.0:
            reported = float(eff)
    proc = fac.get("治理工艺")
    if service == "SO2":
        if reported is not None:
            return {"SO2": reported, "method": f"脱硫设施(填报效率{reported}%)"}
        ms = match_a1_so2(proc)
        if ms:
            effs = [A1[m][A1_COLS["SO2"]] for m in ms]
            return {"SO2": max(effs), "method": "+".join(ms)}
        return None
    if service == "NOx":
        if reported is not None:
            return {"NOx": reported, "method": f"脱硝设施(填报效率{reported}%)"}
        ms = match_a1_nox(proc)
        if ms:
            v = A1[ms[0]][A1_COLS["NOx"]]
            return {"NOx": v, "method": "+".join(ms)}
        return None
    if service == "PM":
        if reported is not None:
            return {"PM2.5": reported, "PM10": reported, "BC": reported, "OC": reported,
                    "method": f"除尘设施(填报效率{reported}%)"}
        ms = match_a1_pm(proc)
        if ms:
            def series(pol):
                col = A1_COLS[pol] if pol != "PM10" else PM_COARSE_COL
                r = 1.0
                for m in ms:
                    r *= (1.0 - A1[m][col] / 100.0)
                return (1.0 - r) * 100.0
            return {"PM2.5": series("PM2.5"), "PM10": series("PM10"),
                    "BC": series("BC"), "OC": series("OC"), "method": "+".join(ms)}
        return None
    if service == "VOC":
        if reported is not None:
            return {"VOC": reported, "method": f"VOCs治理设施(填报效率{reported}%)"}
        ms = match_a1_voc(proc)
        if ms:
            return {"VOC": A1[ms[0]][A1_COLS["VOC"]], "method": "+".join(ms)}
        return None
    return None

def series_eff(values):
    r = 1.0
    for v in values:
        r *= (1.0 - v / 100.0)
    return (1.0 - r) * 100.0

def build_controls(b102, b10102):
    """对每个设备构建控制效率。
    返回 dict: source_id -> {SO2: (eff, method), NOx: (eff, method), PM2.5:..., PM10:..., BC:..., OC:..., VOC:...}
    """
    cf = b10102.copy()
    def og(x):
        return {"GYGL": "GYGL", "DZGL": "DZGL"}.get(x, "OTHER")
    cf["outlet_group"] = cf["对应的排放口代码"].map(og)
    cf["service"] = cf["废气治理设施名称"].map(facility_service)
    controls = {}
    control_notes = {}   # source_id -> list of notes
    for _, row in b102.iterrows():
        sid = row["source_id"]
        credit = row["统一社会信用代码"]
        is_power = pd.notna(row["电站锅炉/燃气轮机编号"])
        group = "DZGL" if is_power else "GYGL"
        low_nox = None
        if is_power:
            v = row["是否采用低氮燃烧技术"]
        else:
            v = row["是否采用低氮燃烧技术.1"]
        low_nox = (isinstance(v, str) and v.strip() == "是")
        facs = cf[(cf["统一社会信用代码"] == credit) & (cf["outlet_group"] == group)]
        res = {}
        methods = {}
        notes = []
        for svc in ["SO2", "NOx", "PM", "VOC"]:
            sub = facs[facs["service"] == svc]
            effs = []          # list of per-facility dict
            undet = []
            for _, f in sub.iterrows():
                fr = facility_eff({"治理效率（%）": f["治理效率（%）"], "治理工艺": f["治理工艺"]}, svc, low_nox)
                if fr is None:
                    undet.append(f["治理设施编号"])
                else:
                    effs.append(fr)
            if undet:
                notes.append(f"{svc}:{len(undet)}座设施无法确定去除效率(工艺与填报效率均缺失),按无治理(η=0)处理")
            if not effs:
                continue
            if svc == "SO2":
                v = series_eff([e["SO2"] for e in effs])
                res["SO2"] = v
                methods["SO2"] = "+".join(sorted({e["method"] for e in effs}))
            elif svc == "NOx":
                v = series_eff([e["NOx"] for e in effs])
                # 低氮燃烧技术(附录A 22%) 与脱硝设施串联
                if low_nox:
                    v = series_eff([v, 22.0])
                    methods["NOx"] = "低氮燃烧技术(22%)+" + "+".join(sorted({e["method"] for e in effs}))
                else:
                    methods["NOx"] = "+".join(sorted({e["method"] for e in effs}))
                res["NOx"] = v
            elif svc == "PM":
                for pol in ["PM2.5", "PM10", "BC", "OC"]:
                    res[pol] = series_eff([e[pol] for e in effs])
                methods["PM"] = "+".join(sorted({e["method"] for e in effs}))
            elif svc == "VOC":
                res["VOC"] = series_eff([e["VOC"] for e in effs])
                methods["VOC"] = "+".join(sorted({e["method"] for e in effs}))
        # 低氮燃烧技术(无脱硝设施时)
        if low_nox and "NOx" not in res:
            res["NOx"] = 22.0
            methods["NOx"] = "低氮燃烧技术(22%)"
        controls[sid] = res
        control_notes[sid] = notes
    return controls, control_notes

# ---------------------------------------------------------------------------
# 组件与计算
