def build_components(row):
    """返回组件列表 [(component_id, 燃料类型, 消耗量, 单位, 燃烧技术), ...]"""
    comps = []
    is_power = pd.notna(row["电站锅炉/燃气轮机编号"])
    tech_col = "电站锅炉燃烧技术" if is_power else "工业锅炉燃烧技术"
    for key, cid, fuel_col, qty_col, unit_col in [
        ("F1", "燃料1类型", "燃料1消耗量", "燃料1消耗量单位"),
        ("F2", "燃料2类型", "燃料2消耗量", "燃料2消耗量单位"),
    ]:
        fuel = row.get(fuel_col)
        qty = row.get(qty_col)
        unit = row.get(unit_col)
        if fuel is None or (isinstance(fuel, float) and math.isnan(fuel)):
            if qty is not None and not (isinstance(qty, float) and math.isnan(qty)) and float(qty) > 0:
                comps.append((cid, None, float(qty), unit if unit is not None else "", tech_col, row))
            continue
        if qty is None or (isinstance(qty, float) and math.isnan(qty)):
            comps.append((cid, str(fuel), None, unit if unit is not None else "", tech_col, row))
        elif float(qty) > 0:
            comps.append((cid, str(fuel), float(qty), str(unit) if unit is not None else "", tech_col, row))
        # 消耗量 <= 0: 无活动, 忽略
    oth = row.get("其他燃料消耗总量（吨标准煤）")
    if oth is not None and not (isinstance(oth, float) and math.isnan(oth)) and float(oth) > 0:
        comps.append(("OTH", None, float(oth), "吨标准煤", tech_col, row))
    return comps

def coal_params(row):
    """返回 (S%, Aar%) 或 None"""
    s = row.get("燃料一平均收到基含硫量")
    a = row.get("燃料一平均收到基灰分（%）")
    if s is None or (isinstance(s, float) and math.isnan(s)) or a is None or (isinstance(a, float) and math.isnan(a)):
        return None
    return (float(s), float(a))

def ef_for_component(cid, fuel, qty, unit, tech_col, row, pollutant):
    """返回 (EF, mode, unit_basis, extra_params) 或 None(无系数/无法计算)"""
    if fuel is None:
        return None
    if fuel in NO_EF_FUELS:
        return None
    fkey = FUEL_MAP.get(fuel)
    if fkey is None:
        return None
    # 燃烧技术
    raw_tech = row.get(tech_col)
    tech = None
    if isinstance(raw_tech, str) and raw_tech.strip():
        tech = TECH_MAP.get(raw_tech.strip())
        if tech is None and raw_tech.strip() != "其他":
            tech = None
    # 煤炭/焦炭: 需要物料衡算参数
    basis = "m3" if fkey in GAS_FUELS else "kg"
    if fkey in ("煤炭", "焦炭"):
        cp = coal_params(row)
        if cp is None:
            return None
        s, a = cp
        if fkey == "焦炭":
            tech_key = None  # 不分技术
            if pollutant == "SO2":
                ef = 2.0 * s * (1.0 - COAL_SR)
                return (ef, "material_balance", basis, {"S_pct": s, "sr": COAL_SR})
            if pollutant in ("CO", "NOx", "VOC"):
                ef = E7[(fkey, "不分技术")][pollutant]
                return (ef, "standard_table_E7", basis, {})
            return None  # PM/BC/OC: 附录C未给出焦炭参数
        if tech is None:
            # 无燃烧技术: SO2 可物料衡算(sr 与技术无关), 其他污染物需要技术参数
            if pollutant == "SO2":
                ef = 2.0 * s * (1.0 - COAL_SR)
                return (ef, "material_balance", basis, {"S_pct": s, "sr": COAL_SR})
            return None
        if pollutant == "SO2":
            ef = 2.0 * s * (1.0 - COAL_SR)
            return (ef, "material_balance", basis, {"S_pct": s, "sr": COAL_SR})
        if pollutant == "PM2.5":
            fpm = COAL_FPM[tech][0]
            ef = a * (1.0 - COAL_AR[tech]) * fpm
            return (ef, "material_balance", basis, {"Aar_pct": a, "ar": COAL_AR[tech], "fPM2.5": fpm})
        if pollutant == "PM10":
            fpm = COAL_FPM[tech][1]
            ef = a * (1.0 - COAL_AR[tech]) * fpm
            return (ef, "material_balance", basis, {"Aar_pct": a, "ar": COAL_AR[tech], "fPM10": fpm})
        if pollutant == "BC":
            ef_pm25 = a * (1.0 - COAL_AR[tech]) * COAL_FPM[tech][0]
            return (ef_pm25 * COAL_FBC[tech], "material_balance", basis,
                    {"EF_PM2.5": ef_pm25, "fBC": COAL_FBC[tech]})
        if pollutant == "OC":
            ef_pm25 = a * (1.0 - COAL_AR[tech]) * COAL_FPM[tech][0]
            return (ef_pm25 * COAL_FOC[tech], "material_balance", basis,
                    {"EF_PM2.5": ef_pm25, "fOC": COAL_FOC[tech]})
        # CO / NOx / VOC
        ef = E7[(fkey, tech)][pollutant]
        return (ef, "standard_table_E7", basis, {"combustion_tech": tech})
    # 非煤燃料
    trow = None
    if fkey in ("其它焦化产品",):
        trow = (fkey, "不分技术")
    elif fkey in GAS_FUELS:
        trow = (fkey, "燃气锅炉")
    else:
        trow = (fkey, "燃油锅炉")
    ef = E7[trow][pollutant]
    return (ef, "standard_table_E7", basis, {})

# ---------------------------------------------------------------------------
# 主流程
# ---------------------------------------------------------------------------
def main():
    b102, b10102, idx = load_inputs()
    b102 = attach_source_ids(b102, idx)

    # 分类
    cats = b102["行业类别代码"].map(classify_industry)
    b102["cat"] = [c[0] for c in cats]
    b102["cat_reason"] = [c[1] for c in cats]

    controls, control_notes = build_controls(b102, b10102)

    # ---------- 决策表 ----------
    decisions = []   # source_id, requested_target, decided_target, disposition, reason_code
    dispositions = []  # source_id, target, disposition, reason_code
    for _, r in b102.iterrows():
        sid = r["source_id"]
        cat = r["cat"]
        rc = r["cat_reason"]
        if cat == "INDUSTRIAL":
            decisions.append((sid, "INDUSTRIAL", "INDUSTRIAL", "included", rc))
            dispositions.append((sid, "INDUSTRIAL", "included", rc))
        elif cat == "POWER_HEAT":
            decisions.append((sid, "INDUSTRIAL", "POWER_HEAT", "excluded_target_mismatch", rc))
            dispositions.append((sid, "POWER_HEAT", "excluded_target_mismatch", rc))
        else:
            decisions.append((sid, "INDUSTRIAL", "OUT_OF_SCOPE", "excluded_out_of_scope", rc))
            dispositions.append((sid, "OUT_OF_SCOPE", "excluded_out_of_scope", rc))

    # ---------- 核算项 ----------
    items = []
    exceptions = []
    exc_seen = {}

    def add_exc(code, sid, pollutant, root_cause, action):
        key = (code, root_cause)
        if key not in exc_seen:
            exc_seen[key] = (sid, pollutant, root_cause, action)
        else:
            exc_seen[key] = (exc_seen[key][0], exc_seen[key][1], exc_seen[key][2], exc_seen[key][3])

    for _, r in b102.iterrows():
        sid = r["source_id"]
        cat = r["cat"]
        if cat != "INDUSTRIAL":
            for pol in POLLUTANTS:
                items.append({
                    "source_id": sid,
                    "target": cat,
                    "pollutant": pol,
                    "status": "not_involved",
                    "method": "",
                    "activity_record_json": "[]",
                    "parameter_record_json": "[]",
                    "control_record_json": "[]",
                    "generation_t": "",
                    "emission_t": "",
                    "standard_reference": "",
                    "reason_code": "not_involved_" + ("power_heat" if cat == "POWER_HEAT" else "out_of_scope"),
                })
            continue

        comps = build_components(r)
        # 燃料信息整体缺失
        fuel_type_missing = all(c[1] is None for c in comps)
        if fuel_type_missing:
            for pol in POLLUTANTS:
                items.append({
                    "source_id": sid, "target": "INDUSTRIAL", "pollutant": pol,
                    "status": "information_insufficient", "method": "",
                    "activity_record_json": "[]", "parameter_record_json": "[]",
                    "control_record_json": "[]",
                    "generation_t": "", "emission_t": "",
                    "standard_reference": "",
                    "reason_code": "info_fuel_type_missing",
                })
            add_exc("EXC-FUEL-TYPE-MISSING", sid, "ALL",
                    "基102设备记录无任何燃料类型与消耗量(燃料1/燃料2/其他燃料均无有效数据)",
                    "核实设备实际燃料种类与消耗量后补算")
            continue

        # 每污染物计算
        for pol in POLLUTANTS:
            act = []
            par = []
            ctl = []
            gen = 0.0
            emis = 0.0
            all_computable = True
            any_component = False
            missing_causes = []
            for (cid, fuel, qty, unit, tech_col, rowref) in comps:
                any_component = True
                # activity
                if qty is None:
                    act.append({"component_id": cid, "value": None, "unit": unit if unit else ""})
                    all_computable = False
                    missing_causes.append(f"{cid}:消耗量缺失")
                    par.append({"component_id": cid, "parameter_id": f"EF_{pol}",
                                "mode": "not_available", "value": None, "unit": ""})
                    ctl.append({"component_id": cid, "method": "无控制(未计算)", "efficiency": 0.0,
                                "fine_efficiency": None, "coarse_efficiency": None})
                    continue
                act.append({"component_id": cid, "value": qty, "unit": unit if unit else ""})
                # control
                ctrl = controls.get(sid, {})
                cmethod = ""
                if pol == "PM10":
                    fine = ctrl.get("PM2.5", 0.0)
                    coarse = ctrl.get("PM10", 0.0)
                    ceff = fine
                    if "PM" in ctrl:
                        cmethod = ctrl.get("PM_method", "")
                    eff_used = None
                    ctl.append({"component_id": cid, "method": cmethod if cmethod else "无适用治理",
                                "efficiency": eff_used, "fine_efficiency": round(fine, 6),
                                "coarse_efficiency": round(coarse, 6)})
                else:
                    eff = ctrl.get(pol, 0.0)
                    if pol in ctrl:
                        cmethod = ctrl.get(pol + "_method", "")
                    ctl.append({"component_id": cid,
                                "method": cmethod if cmethod else "无适用治理",
                                "efficiency": round(eff, 6),
                                "fine_efficiency": None, "coarse_efficiency": None})
                # EF
                efres = ef_for_component(cid, fuel, qty, unit, tech_col, rowref, pol)
                if efres is None:
                    all_computable = False
                    if fuel in NO_EF_FUELS:
                        missing_causes.append(f"{cid}({fuel}):标准未提供该燃料产生系数")
                        par.append({"component_id": cid, "parameter_id": f"EF_{pol}",
                                    "mode": "not_available", "value": None, "unit": "",
                                    "note": f"燃料[{fuel}]在T/CSES 144-2024附录E表E.7无对应产生系数"})
                    else:
                        missing_causes.append(f"{cid}({fuel}):燃烧技术或燃料参数缺失,无法选取/计算产生系数")
                        par.append({"component_id": cid, "parameter_id": f"EF_{pol}",
                                    "mode": "not_available", "value": None, "unit": "",
                                    "note": "燃烧技术或燃料参数缺失"})
                    continue
                ef, mode, basis, extra = efres
                par.append({"component_id": cid, "parameter_id": f"EF_{pol}", "mode": mode,
                            "value": round(ef, 8), "unit": "g/kg" if basis == "kg" else "g/m3",
                            "extra": extra})
                # 计算: E = A × EF × (1-η) ; A 需换算到 EF 基准单位
                if basis == "m3":
                    a = qty * 1e4          # 万立方米 -> 立方米
                else:
                    a = qty * 1e3          # 吨 -> 千克
                eta = ctrl.get(pol, 0.0) if pol != "PM10" else ctrl.get("PM10", 0.0)
                if pol == "PM10":
                    eta = ctrl.get("PM10", 0.0)
                g = a * ef * 1e-6          # g -> 吨
                e = g * (1.0 - eta / 100.0)
                gen += g
                emis += e
