                continue
            # 低氮/控制备注
            notes = control_notes.get(sid, [])
            for n in notes:
                add_exc("EXC-CONTROL-EFF-MISSING", sid, pol, n,
                        "核实治理设施实际去除效率后更新; 当前该污染物按无治理(η=0)处理")
            if all_computable:
                items.append({
                    "source_id": sid, "target": "INDUSTRIAL", "pollutant": pol,
                    "status": "calculated",
                    "method": "emission_factor_method_eq2",
                    "activity_record_json": json.dumps(act, ensure_ascii=False),
                    "parameter_record_json": json.dumps(par, ensure_ascii=False),
                    "control_record_json": json.dumps(ctl, ensure_ascii=False),
                    "generation_t": round(gen, 8), "emission_t": round(emis, 8),
                    "standard_reference": "T/CSES 144-2024 第8.3节 公式(2)",
                    "reason_code": "calc_ok",
