            else:
                cause = ";".join(sorted(set(missing_causes)))
                if any("标准未提供该燃料产生系数" in c for c in missing_causes):
                    rc = "info_fuel_no_ef_in_standard"
                    add_exc("EXC-NO-EF-FUEL", sid, pol, cause,
                            "补充该燃料产生系数(如生态环境部公告2021年第24号或2014年第92号附件5)后重算")
                elif any("消耗量缺失" in c for c in missing_causes):
                    rc = "info_activity_missing"
                    add_exc("EXC-ACTIVITY-MISSING", sid, pol, cause, "补充燃料消耗量后重算")
                elif any("燃烧技术或燃料参数缺失" in c for c in missing_causes):
                    rc = "info_combustion_tech_or_param_missing"
                    add_exc("EXC-COAL-TECH-MISSING", sid, pol, cause,
                            "补充燃烧技术(煤粉炉/流化床炉/层燃炉等)或燃料参数后重算")
